pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(rev), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert from callee");
    }
    receive() external payable {
        revert("revert from callee");
    }
}
